import React from 'react';

const Projects = () => {
  const projects = [
    {
      title: 'React Portfolio',
      description: 'A responsive portfolio website built with React showcasing modern development practices and clean design.',
      tech: ['React', 'CSS3', 'JavaScript'],
      github: 'https://github.com/Cluster3824'
    },
    {
      title: 'Web Development Projects',
      description: 'Various web applications demonstrating full-stack development capabilities and modern design principles.',
      tech: ['React', 'Node.js', 'MongoDB'],
      github: 'https://github.com/Cluster3824'
    }
  ];

  return (
    <section id="projects" className="projects">
      <div className="container">
        <h2>Featured Projects</h2>
        <div className="projects-grid">
          {projects.map((project, index) => (
            <div key={index} className="project-card">
              <h3>{project.title}</h3>
              <p>{project.description}</p>
              <div className="project-tech">
                {project.tech.map((tech, techIndex) => (
                  <span key={techIndex}>{tech}</span>
                ))}
              </div>
              <div className="project-links">
                <a href={project.github} target="_blank" rel="noopener noreferrer">
                  <i className="fab fa-github"></i> Code
                </a>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Projects;
